import{_ as a,o as i,c as t,a2 as r}from"./chunks/framework.CDpkVv68.js";const g=JSON.parse('{"title":"Spell Memory and Familiarity","description":"","frontmatter":{},"headers":[],"relativePath":"guide/magic/memory-and-familiarity.md","filePath":"guide/magic/memory-and-familiarity.md"}'),n={name:"guide/magic/memory-and-familiarity.md"};function o(s,e,l,m,d,p){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="spell-memory-and-familiarity" tabindex="-1">Spell Memory and Familiarity <a class="header-anchor" href="#spell-memory-and-familiarity" aria-label="Permalink to &quot;Spell Memory and Familiarity&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> <strong>Implementation:</strong> this redesign is not established as implemented. <strong>Availability:</strong> not established as live. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-09 against Batch 04.</p><p><a href="/Syrolands-Public/game-design/magic/memory-and-familiarity.html">Full design specification</a></p><p>Two mages with the same Magery could have very different practice with the same spell. Familiarity belongs to each Core Pattern and does not consume skillcap.</p><p>Active Memory is a limited prepared loadout. A memorized spell needs no extra lookup before the normal casting sequence; that does not make its cast instantaneous. A known but unmemorized spell requires extra reference/recall, with more familiar patterns tending toward shorter delays.</p><p>Imagine being chased while finding Remove Curse in your book, reading it and trying to cast under pressure. Visible reading and divided attention are desired experiences, not current client features. Keys, page navigation, accessibility and interruption rules remain undecided.</p><p>INT may support memory capacity and complex patterns; Meditation may help rearrange and prepare them. Memorizing a base spell may not prepare every modified variant. Exact capacities, delays and preparation costs remain open.</p><p><a href="/Syrolands-Public/guide/magic/spellbooks-scrolls-and-reagents.html">Scrolls and grimoires</a> may offer useful reference tools without making all known spells immediately ready.</p>',8)])])}const y=a(n,[["render",o]]);export{g as __pageData,y as default};
